"""Validators over depot harness outputs, continued from validators.py.

Each validator takes the collected items and returns (passed, measured).
"""

from __future__ import annotations

from typing import Any, Iterable

# Inclusive bounds for a supplier's reliability score (assumed 0..100).
RELIABILITY_MIN: int = 0
RELIABILITY_MAX: int = 100


def _exceeds_capacity(entry: dict[str, Any]) -> bool:
    """True when a warehouse's peak usage is above its capacity."""
    return entry["max_units"] > entry["capacity"]


def v7(entries: Iterable[dict[str, Any]]) -> tuple[bool, list[str]]:
    """V7: every warehouse's capacity was respected across runs.

    Each entry: {"wh": str, "capacity": int, "max_units": int}.
    Passes when max_units <= capacity for every entry.
    Returns (passed, measured) where measured is the list of warehouse ids
    whose max_units exceeded capacity.
    """
    over: list[str] = []
    for entry in entries:
        if _exceeds_capacity(entry):
            over.append(entry["wh"])
    return (len(over) == 0, over)


def _unnotified(expired: Iterable[list[Any]], notified: Iterable[list[Any]]) -> list[list[Any]]:
    """Return the expired [sku, wh, qty] items with no exact match in notified."""
    notified_set = {tuple(item) for item in notified}
    return [item for item in expired if tuple(item) not in notified_set]


def v8(entries: Iterable[dict[str, Any]]) -> tuple[bool, list[list[Any]]]:
    """V8: all expiries were notified.

    Each entry: {"expired": [[sku, wh, qty], ...], "notified": [[sku, wh, qty], ...]}.
    Passes when every expired [sku, wh, qty] has an identical entry in notified.
    Returns (passed, measured) where measured is the list of expired items
    that were not notified.
    """
    missing: list[list[Any]] = []
    for entry in entries:
        missing.extend(_unnotified(entry["expired"], entry["notified"]))
    return (len(missing) == 0, missing)


def _reliability_in_range(entry: dict[str, Any]) -> bool:
    """True when a supplier's reliability is within the inclusive bounds."""
    return RELIABILITY_MIN <= entry["reliability"] <= RELIABILITY_MAX


def v9(entries: Iterable[dict[str, Any]]) -> tuple[bool, list[str]]:
    """V9: every supplier's reliability stayed in range.

    Each entry: {"supplier": str, "reliability": int}.
    Passes when RELIABILITY_MIN <= reliability <= RELIABILITY_MAX for every entry.
    Returns (passed, measured) where measured is the list of supplier ids
    whose reliability fell outside the range.
    """
    out_of_range: list[str] = []
    for entry in entries:
        if not _reliability_in_range(entry):
            out_of_range.append(entry["supplier"])
    return (len(out_of_range) == 0, out_of_range)
