"""Tests for validators_later.py (V7, V8, V9)."""

from __future__ import annotations

import unittest

from validators_later import v7, v8, v9


class TestV7(unittest.TestCase):
    def test_empty_passes(self) -> None:
        self.assertEqual(v7([]), (True, []))

    def test_at_capacity_passes(self) -> None:
        entries = [{"wh": "A", "capacity": 10, "max_units": 10}]
        self.assertEqual(v7(entries), (True, []))

    def test_over_capacity_reported(self) -> None:
        entries = [
            {"wh": "A", "capacity": 10, "max_units": 11},
            {"wh": "B", "capacity": 10, "max_units": 5},
            {"wh": "C", "capacity": 3, "max_units": 4},
        ]
        self.assertEqual(v7(entries), (False, ["A", "C"]))


class TestV8(unittest.TestCase):
    def test_empty_passes(self) -> None:
        self.assertEqual(v8([]), (True, []))

    def test_all_notified_passes(self) -> None:
        entries = [
            {
                "expired": [["milk", "W1", 3]],
                "notified": [["milk", "W1", 3], ["eggs", "W2", 1]],
            }
        ]
        self.assertEqual(v8(entries), (True, []))

    def test_missing_notification_reported(self) -> None:
        entries = [
            {
                "expired": [["milk", "W1", 3], ["eggs", "W2", 1]],
                "notified": [["milk", "W1", 3]],
            }
        ]
        self.assertEqual(v8(entries), (False, [["eggs", "W2", 1]]))

    def test_quantity_mismatch_counts_as_missing(self) -> None:
        entries = [
            {
                "expired": [["milk", "W1", 3]],
                "notified": [["milk", "W1", 2]],
            }
        ]
        self.assertEqual(v8(entries), (False, [["milk", "W1", 3]]))

    def test_notifications_do_not_cross_entries(self) -> None:
        entries = [
            {"expired": [["milk", "W1", 3]], "notified": []},
            {"expired": [], "notified": [["milk", "W1", 3]]},
        ]
        self.assertEqual(v8(entries), (False, [["milk", "W1", 3]]))


class TestV9(unittest.TestCase):
    def test_empty_passes(self) -> None:
        self.assertEqual(v9([]), (True, []))

    def test_bounds_are_inclusive(self) -> None:
        entries = [
            {"supplier": "S1", "reliability": 0},
            {"supplier": "S2", "reliability": 100},
        ]
        self.assertEqual(v9(entries), (True, []))

    def test_out_of_range_reported(self) -> None:
        entries = [
            {"supplier": "S1", "reliability": -1},
            {"supplier": "S2", "reliability": 50},
            {"supplier": "S3", "reliability": 101},
        ]
        self.assertEqual(v9(entries), (False, ["S1", "S3"]))


if __name__ == "__main__":
    unittest.main()
